require_once __DIR__ . '/../../helpers/auth.php'; require_once __DIR__ . '/../../helpers/csrf.php'; require_once __DIR__ . '/../../models/Counseling.php'; require_once __DIR__ . '/../../models/ServiceRequest.php';
require_role(['SUPER_ADMIN', 'CHURCH_ADMIN', 'STAFF']); $requestId = filter_input(INPUT_GET, 'request_id', FILTER_VALIDATE_INT); $request = $requestId ? ServiceRequest::find($requestId) : null; if (!$request) { http_response_code(404); exit('Service request not found.'); } $case = null; $lookup = database()->prepare('SELECT id FROM counseling_cases WHERE service_request_id = :id'); $lookup->execute(['id' => $requestId]); $caseId = $lookup->fetchColumn(); if ($caseId) { $case = Counseling::findCase((int) $caseId); } $counselors = Counseling::counselors(); $errors = [];
